<?php require __DIR__.'/bootstrap.php';try{$in=internal_input();$status=in_array($in['status']??'', ['online','away','offline'],true)?$in['status']:'offline';Database::execute('INSERT INTO chat_presence(user_id,status,socket_id,last_seen_at,updated_at) SELECT id,?,?,NOW(),NOW() FROM users WHERE id=? ON DUPLICATE KEY UPDATE status=VALUES(status),socket_id=VALUES(socket_id),last_seen_at=NOW(),updated_at=NOW()',[(int)($in['user_id']??0),$status,MessengerSecurity::text($in['socket_id']??'',190),(int)($in['user_id']??0)]);internal_json(['ok'=>true]);}catch(Throwable $e){internal_json(['ok'=>false],422);}
